package com.comandos.inventory.model;import com.comandos.core.model.*;import jakarta.persistence.*;
@Entity@Table(name="erp_recall",uniqueConstraints=@UniqueConstraint(columnNames={"organization_id","recall_number"}))public class Recall extends CoreEntity{@ManyToOne(optional=false)@JoinColumn(name="organization_id",nullable=false)public Organization organization;@ManyToOne@JoinColumn(name="unit_id")public OrganizationalUnit unit;@Column(name="recall_number",nullable=false)public String number;@Column(nullable=false)public String reason;@Column(nullable=false)public String status;@Column(length=255)public String description;}
